import os
import boto3
from botocore.exceptions import ClientError

def sign_or_verify_key(payload, config=None):
    config = config or {}
    kms_client = boto3.client('kms', region_name=config.get('region', 'us-east-1'))
    key_id = config.get('key_id', os.getenv('AWS_KMS_KEY_ID'))
    if not key_id:
        raise ValueError("Key ID must be provided via config or AWS_KMS_KEY_ID environment variable")
    try:
        response = kms_client.sign(
            KeyId=key_id,
            Message=payload,
            MessageType='RAW',
            SigningAlgorithm='RSASSA_PKCS1_V1_5_SHA_256'
        )
        result = response['Signature']
    except ClientError as e:
        result = f"Error: {e.response['Error']['Message']}"
    return result
